import React, { useState } from 'react';
import { ApolloClient, InMemoryCache, HttpLink, ApolloProvider, gql, useQuery } from '@apollo/client';
import { setContext } from '@apollo/client/link/context';
import './App.css';
import Auth from './components/Auth';
import Artists from './components/Artists';
import Albums from './components/Albums';
import Tracks from './components/Tracks';
import Playlists from './components/Playlists';
import Search from './components/Search';

// ============================================================
// APOLLO CLIENT
// ============================================================
const httpLink = new HttpLink({
  uri: 'http://localhost:4000/graphql',
  credentials: 'include',
});

const authLink = setContext((_, { headers }) => {
  const token = localStorage.getItem('token');
  return {
    headers: {
      ...headers,
      authorization: token ? `Bearer ${token}` : '',
    },
  };
});

const client = new ApolloClient({
  link: authLink.concat(httpLink),
  cache: new InMemoryCache(),
  defaultOptions: {
    watchQuery: { errorPolicy: 'all' },
    query:      { errorPolicy: 'all' },
    mutate:     { errorPolicy: 'all' },
  },
});

// ============================================================
// QUERIES
// ============================================================
const GENRES_QUERY = gql`
  query Genres {
    genres {
      id
      name
      picture_medium
      picture_xl
    }
  }
`;

const RADIOS_QUERY = gql`
  query Radios {
    radios {
      id
      title
      description
      picture_medium
      picture_xl
      tracklist
    }
  }
`;

const EDITORIALS_QUERY = gql`
  query Editorials {
    editorials {
      id
      name
      picture_medium
      picture_xl
    }
  }
`;

const PODCASTS_QUERY = gql`
  query Podcasts {
    podcasts {
      id
      title
      description
      available
      fans
      picture_medium
      picture_xl
      link
    }
  }
`;

// ============================================================
// HELPER : image avec fallback texte
// ============================================================
function ImgWithFallback({ src, alt, style, fallbackChar = '🎵' }) {
  const [failed, setFailed] = useState(false);
  if (!src || failed) {
    return (
      <div style={{
        ...style,
        background: '#f0f0f0',
        display: 'flex', alignItems: 'center', justifyContent: 'center',
        fontSize: '2rem', color: '#bbb',
        borderRadius: style?.borderRadius || 4,
        flexShrink: 0,
      }}>
        {fallbackChar}
      </div>
    );
  }
  return (
    <img
      src={src}
      alt={alt}
      style={style}
      onError={() => setFailed(true)}
    />
  );
}

function Spinner() {
  return <div className="loading">⏳ Chargement...</div>;
}

// ============================================================
// COMPOSANT : Genres
// ============================================================
function Genres({ token }) {
  const { data, loading, error } = useQuery(GENRES_QUERY, {
    context: { headers: { authorization: `Bearer ${token}` } },
  });

  if (loading) return <Spinner />;
  if (error)   return <div className="error">❌ Erreur : {error.message}</div>;

  const genres = data?.genres || [];

  return (
    <div>
      <h2>🎼 Genres</h2>
      {genres.length === 0 && <div className="empty">📭 Aucun genre</div>}
      <div className="items-grid">
        {genres.map((genre) => (
          <div key={genre.id} className="card" style={{ textAlign: 'center' }}>
            <ImgWithFallback
              src={genre.picture_medium}
              alt={genre.name}
              fallbackChar="🎼"
              style={{ width: '100%', height: 160, objectFit: 'cover', borderRadius: 4, marginBottom: '1rem' }}
            />
            <h3 style={{ margin: '0 0 0.25rem' }}>{genre.name}</h3>
            <div className="card-meta"><span>ID : {genre.id}</span></div>
          </div>
        ))}
      </div>
    </div>
  );
}

// ============================================================
// COMPOSANT : Radios
// ============================================================
function Radios({ token }) {
  const { data, loading, error } = useQuery(RADIOS_QUERY, {
    context: { headers: { authorization: `Bearer ${token}` } },
  });

  if (loading) return <Spinner />;
  if (error)   return <div className="error">❌ Erreur : {error.message}</div>;

  const radios = data?.radios || [];

  return (
    <div>
      <h2>📻 Radios</h2>
      {radios.length === 0 && <div className="empty">📭 Aucune radio</div>}
      <div className="items-grid">
        {radios.map((radio) => (
          <div key={radio.id} className="card">
            <ImgWithFallback
              src={radio.picture_medium}
              alt={radio.title}
              fallbackChar="📻"
              style={{ width: '100%', height: 160, objectFit: 'cover', borderRadius: 4, marginBottom: '1rem' }}
            />
            <h3>{radio.title}</h3>
            {radio.description && (
              <p style={{ fontSize: '0.875rem', color: '#666', margin: '0.25rem 0 0.75rem' }}>
                {radio.description}
              </p>
            )}
            {radio.tracklist && (
              <div className="card-actions">
                <a
                  href={radio.tracklist}
                  target="_blank"
                  rel="noopener noreferrer"
                  className="btn-primary"
                  style={{ textDecoration: 'none', display: 'inline-block', fontSize: '0.85rem' }}
                >
                  🎵 Tracklist
                </a>
              </div>
            )}
          </div>
        ))}
      </div>
    </div>
  );
}




// ============================================================
// APP PRINCIPALE
// ============================================================
function App() {
  const [token, setToken]         = useState(localStorage.getItem('token'));
  const [user, setUser]           = useState(JSON.parse(localStorage.getItem('user') || 'null'));
  const [activeTab, setActiveTab] = useState('artists');

  const handleLogin = (t, u) => {
    localStorage.setItem('token', t);
    localStorage.setItem('user', JSON.stringify(u));
    setToken(t);
    setUser(u);
  };

  const handleLogout = () => {
    localStorage.removeItem('token');
    localStorage.removeItem('user');
    setToken(null);
    setUser(null);
  };

  if (!token) {
    return (
      <ApolloProvider client={client}>
        <div className="app">
          <Auth onLogin={handleLogin} />
        </div>
      </ApolloProvider>
    );
  }

  const tabs = [
    { id: 'search',     label: '🔍 Recherche'  },
    { id: 'artists',    label: '🎤 Artistes'   },
    { id: 'albums',     label: '💿 Albums'     },
    { id: 'tracks',     label: '🎵 Pistes'     },
    { id: 'playlists',  label: '📋 Playlists'  },
    { id: 'genres',     label: '🎼 Genres'     },
  ];

  return (
    <ApolloProvider client={client}>
      <div className="app">
        <header className="header">
          <h1>🎵 Music GraphQL Tester</h1>
          <div className="user-info">
            <span>👤 {user?.username} ({user?.role})</span>
            <button onClick={handleLogout} className="logout-btn">Déconnexion</button>
          </div>
        </header>

        <nav className="nav-tabs">
          {tabs.map((tab) => (
            <button
              key={tab.id}
              className={`tab ${activeTab === tab.id ? 'active' : ''}`}
              onClick={() => setActiveTab(tab.id)}
            >
              {tab.label}
            </button>
          ))}
        </nav>

        <main className="content">
          {activeTab === 'search'     && <Search     token={token} />}
          {activeTab === 'artists'    && <Artists    token={token} userRole={user?.role} />}
          {activeTab === 'albums'     && <Albums     token={token} userRole={user?.role} />}
          {activeTab === 'tracks'     && <Tracks     token={token} userRole={user?.role} />}
          {activeTab === 'playlists'  && <Playlists  token={token} />}
          {activeTab === 'genres'     && <Genres     token={token} />}
        </main>
      </div>
    </ApolloProvider>
  );
}

export default App;
